// 로컬(시험) D1 을 비우고 마이그레이션을 적용한다. 계정은 시험이 이메일 OTP 로 직접 만든다(SIGNUP_ALLOWLIST=@agent.test).
//
//   node scripts/db-local.mjs [--persist-to .wrangler/test-state]
import { spawnSync } from 'node:child_process';
import { rmSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const i = process.argv.indexOf('--persist-to');
const persist = i > 0 ? process.argv[i + 1] : '.wrangler/test-state';
rmSync(join(root, persist), { recursive: true, force: true });
const r = spawnSync('npx', ['wrangler', 'd1', 'migrations', 'apply', 'DB', '--local', '--persist-to', persist], { cwd: root, stdio: 'inherit' });
if (r.status !== 0) process.exit(r.status ?? 1);
// 운영 배포: 리소스 확인 → 빌드(점검 포함) → 비밀값 확인 → D1 마이그레이션 → wrangler deploy → 운영 주소에서 결과 확인.
//
//   set -a; . ~/.config/irumx/cloud.env; set +a
//   CLOUDFLARE_API_TOKEN=$CF_API_TOKEN CLOUDFLARE_ACCOUNT_ID=$CF_ACCOUNT_ID npm run deploy
//   node scripts/deploy.mjs --verify-only     (배포 없이 운영 확인만)
//   node scripts/deploy.mjs --secrets-file <경로>   (처음 배포: 비밀값을 같은 버전에 함께 올린다. 파일은 저장소 밖에 둔다)
//
// 'Deployment complete' 를 믿지 않고, 운영 주소가 방금 만든 파일을 바이트 단위로 돌려주는지와 보안 동작을 확인한다.
// client.irumx.app 의 Worker·D1·R2 는 건드리지 않는다(이름·ID 는 verify-build 가 이미 막는다).
import { spawnSync } from 'node:child_process';
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join, resolve } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
const LIVE = 'https://agent.irumx.app';
const NAME = 'irumx-agent';
const REQUIRED_SECRETS = ['BETTER_AUTH_SECRET', 'CREDENTIAL_KEK_V1', 'RESEND_API_KEY'];
const verifyOnly = process.argv.includes('--verify-only');
const si = process.argv.indexOf('--secrets-file');
const secretsFile = si > 0 ? resolve(process.argv[si + 1] ?? '') : null;

function run(cmd, args, { capture = false } = {}) {
  console.log(`\n$ ${cmd} ${args.join(' ')}`);
  const r = spawnSync(cmd, args, { cwd: root, stdio: capture ? ['ignore', 'pipe', 'inherit'] : 'inherit', encoding: 'utf8' });
  if (r.status !== 0) {
    console.error(`실패: ${cmd} ${args.join(' ')} (종료 코드 ${r.status})`);
    process.exit(r.status ?? 1);
  }
  return r.stdout ?? '';
}
const quiet = (cmd, args) => spawnSync(cmd, args, { cwd: root, encoding: 'utf8' });

if (!verifyOnly) {
  for (const k of ['CLOUDFLARE_API_TOKEN', 'CLOUDFLARE_ACCOUNT_ID'])
    if (!process.env[k]) {
      console.error(`${k} 가 없다. 배포 셸에서 export 한 뒤 다시 실행한다.`);
      process.exit(1);
    }
  // 1) 에이전트 전용 리소스(R2·큐). 없으면 만든다 — client 리소스와 이름이 다르다
  const buckets = quiet('npx', ['wrangler', 'r2', 'bucket', 'list']).stdout ?? '';
  if (!/name:\s+irumx-agent-files\b/.test(buckets)) run('npx', ['wrangler', 'r2', 'bucket', 'create', 'irumx-agent-files']);
  const queues = quiet('npx', ['wrangler', 'queues', 'list']).stdout ?? '';
  for (const q of ['irumx-agent-runs', 'irumx-agent-runs-dlq']) if (!new RegExp(`\\b${q}\\b(?!-)`).test(queues)) run('npx', ['wrangler', 'queues', 'create', q]);
  // 2) 빌드(타입 점검·빌드 점검 포함)
  run('npm', ['run', 'build']);
  // 3) 비밀값 — 이미 올라가 있거나 이번에 함께 올린다. 하나라도 없으면 배포하지 않는다
  let have = [];
  const listed = quiet('npx', ['wrangler', 'secret', 'list', '--format', 'json']);
  if (listed.status === 0) have = JSON.parse(listed.stdout || '[]').map((s) => s.name);
  if (secretsFile) {
    const text = readFileSync(secretsFile, 'utf8');
    for (const line of text.split('\n')) {
      const m = line.match(/^\s*([A-Z0-9_]+)\s*=/);
      if (m) have.push(m[1]);
    }
  }
  const missing = REQUIRED_SECRETS.filter((k) => !have.includes(k));
  if (missing.length) {
    console.error(`비밀값이 없다: ${missing.join(', ')} — docs/deployment.md 의 '비밀값' 절차대로 넣고 다시 실행한다.`);
    process.exit(1);
  }
  // 4) D1 마이그레이션(에이전트 전용 DB) → 배포
  run('npx', ['wrangler', 'd1', 'migrations', 'apply', 'DB', '--remote']);
  run('npx', ['wrangler', 'deploy', ...(secretsFile ? ['--secrets-file', secretsFile] : [])]);
}

const get = (path, init) => fetch(LIVE + path, { redirect: 'manual', ...init });
const local = readFileSync(join(root, 'dist/client/index.html'));
let ok = false;
for (let i = 0; i < 60 && !ok; i++) {
  const res = await get(`/?v=${Date.now()}`, { cache: 'no-store' }).catch(() => null);
  ok = !!res && res.status === 200 && Buffer.from(await res.arrayBuffer()).equals(local);
  if (!ok) await new Promise((r) => setTimeout(r, 5000));
}
if (!ok) {
  console.error('운영 index.html 이 로컬 빌드와 다르다(전파 지연이거나 배포 실패).');
  process.exit(1);
}
const checks = [];
const appHtml = readFileSync(join(root, 'dist/client/app.html'), 'utf8');
const appJs = appHtml.match(/\/assets\/[^"]+\.js/)?.[0];
if (appJs) checks.push([`${appJs} 일치`, Buffer.from(await (await get(appJs)).arrayBuffer()).equals(readFileSync(join(root, 'dist/client', appJs)))]);
for (const f of readdirSync(join(root, 'dist/client/assets')).filter((x) => /\.js$/.test(x)).slice(0, 40)) {
  checks.push([`/assets/${f} 일치`, Buffer.from(await (await get(`/assets/${f}`)).arrayBuffer()).equals(readFileSync(join(root, 'dist/client/assets', f)))]);
}
checks.push(['없는 조각 404(옛 탭은 새로 고침)', (await get('/assets/chat-gone0000.js')).status === 404]);
const shell = await get('/app/w/abcdefghijkmnpqr/agents');
const sh = shell.headers;
const shellBody = await shell.text();
checks.push([`화면 주소 → 앱 셸(${shell.status})`, shell.status === 200 && shellBody.includes('id="root"') && !shellBody.includes('이룸검수')]);
checks.push(['앱 셸 CSP·no-store·noindex', (sh.get('content-security-policy') ?? '').includes("script-src 'self'") && (sh.get('cache-control') ?? '').includes('no-store') && (sh.get('x-robots-tag') ?? '').includes('noindex')]);
checks.push(['HSTS', !!sh.get('strict-transport-security')]);
const me = await get('/api/me');
checks.push([`/api/me 비로그인(${me.status})`, me.status === 200 && (await me.text()).includes('"user":null')]);
checks.push(['워크스페이스 API 비로그인 401', (await get('/api/w/abcdefghijkmnpqr/agents')).status === 401]);
checks.push(['실행 이벤트 비로그인 401', (await get('/api/w/abcdefghijkmnpqr/runs/abcdefghijkmnpqr/events')).status === 401]);
const nf = await get('/api/nothing-here');
checks.push([`없는 API → JSON 404(${nf.status})`, nf.status === 404 && (nf.headers.get('content-type') ?? '').includes('application/json')]);
checks.push(['시험 전용 경로 닫힘(404)', (await get('/api/__test/hook', { method: 'POST', headers: { Origin: LIVE, 'Content-Type': 'application/json' }, body: '{}' })).status === 404]);
const forged = await get('/api/me/profile', { method: 'POST', headers: { Origin: 'https://client.irumx.app', 'Content-Type': 'application/json' }, body: '{"name":"x"}' });
checks.push([`다른 출처(client 포함) 쓰기 403(${forged.status})`, forged.status === 403]);
const otp = await get('/api/auth/email-otp/send-verification-otp', { method: 'POST', headers: { Origin: LIVE, 'Content-Type': 'application/json' }, body: JSON.stringify({ email: 'nobody@example.invalid', type: 'sign-in' }) });
checks.push([`로그인 코드 API(${otp.status}, 초대 안 된 주소는 보내지 않음)`, otp.status === 200]);
const cimd = await get('/oauth/client.json');
const cimdBody = cimd.status === 200 ? await cimd.json() : {};
checks.push(['OAuth 클라이언트 문서(CIMD)', cimdBody.client_id === `${LIVE}/oauth/client.json` && cimdBody.application_type === 'web' && cimdBody.token_endpoint_auth_method === 'none']);
checks.push(['개인정보 처리방침 200', (await get('/privacy')).status === 200]);
const robots = await (await get('/robots.txt')).text();
checks.push(['robots.txt(사이트맵·공유 그림 허용)', robots.includes('Allow: /$') && robots.includes('Disallow: /') && robots.includes('Sitemap: https://agent.irumx.app/sitemap.xml') && robots.includes('Allow: /og.png')]);
const og = await get('/og.png');
checks.push([`공유 그림 og.png(${og.status})`, og.status === 200 && (og.headers.get('content-type') ?? '').startsWith('image/png') && Buffer.from(await og.arrayBuffer()).equals(readFileSync(join(root, 'dist/client/og.png')))]);
const sm = await get('/sitemap.xml');
checks.push([`sitemap.xml(${sm.status}, utf-8)`, sm.status === 200 && (sm.headers.get('content-type') ?? '').includes('charset=utf-8') && (await sm.text()).includes('<loc>https://agent.irumx.app/</loc>')]);
const llms = await get('/llms.txt');
checks.push([`llms.txt(${llms.status}, utf-8)`, llms.status === 200 && (llms.headers.get('content-type') ?? '').includes('charset=utf-8') && (await llms.text()).includes('# 이룸에이전트')]);
const font = await get('/fonts/irumx-ui.woff2', { method: 'HEAD' });
checks.push([`글꼴 immutable(${font.status})`, font.status === 200 && (font.headers.get('cache-control') ?? '').includes('immutable')]);
// 쿠키를 상위 도메인(.irumx.app)에 걸지 않는다 — 로그인 응답의 Set-Cookie 에 Domain 이 없어야 한다
const cookie = otp.headers.get('set-cookie') ?? '';
checks.push(['상위 도메인 쿠키 없음', !/domain=\.?irumx\.app/i.test(cookie)]);
for (const [name, pass] of checks) console.log(`${pass ? '✓' : '✗'} ${name}`);
if (checks.some(([, p]) => !p)) process.exit(1);
console.log(`\n운영 반영 확인: ${LIVE} (${NAME})`);
