/**
 * 결과물 — 에이전트가 이 공간에 저장한 초안(보고서·답변·표)을 모아 본다. 지금 볼 수 있는 실행의 것만(서버가 거른다).
 * 미리보기는 같은 출처 내려받기 주소를 글자로 읽어 보여 준다(Markdown 은 렌더, JSON·CSV 는 원문).
 */
import { useEffect, useState } from 'react';
import { Link, useSearchParams } from 'react-router';
import { useApi } from '../../lib/api';
import { useWs } from '../../app/context';
import { Empty, Loading, Markdown, PageHead } from '../../components/ui';
import { Icon } from '../../components/icons';
import { ago, fmtBytes, fmtDateTime } from '../../lib/format';
import { useFlash } from '../../lib/flash';

interface Art {
  id: string;
  title: string;
  format: 'markdown' | 'json' | 'csv';
  size: number;
  sha256: string;
  created_at: number;
  run_id: string;
  conversation_id: string | null;
  conversation_title: string | null;
  agent_name: string | null;
  trigger: string;
}

const FORMAT_LABEL: Record<Art['format'], string> = { markdown: '문서', json: 'JSON', csv: '표(CSV)' };

export function Artifacts() {
  const { ws, space, home } = useWs();
  const [params, setParams] = useSearchParams();
  const [q, setQ] = useState('');
  const list = useApi<{ artifacts: Art[] }>(space ? `/api/w/${ws}/spaces/${space}/artifacts${q ? `?q=${encodeURIComponent(q)}` : ''}` : null);
  const open = params.get('open');
  const sp = home?.spaces.find((s) => s.id === space);
  if (!space || list.isLoading) return <Loading />;
  const items = list.data?.artifacts ?? [];
  const current = items.find((x) => x.id === open) ?? null;
  return (
    <div className="content">
      <PageHead title="결과물" lead={`${sp?.kind === 'personal' ? '개인 공간' : '팀 공간'} · ${sp?.name ?? ''} — 에이전트가 저장한 보고서·답변 초안·표입니다. 외부로 보내지 않은 초안이며, 저장한 그대로 바뀌지 않습니다.`} />
      <div className="art-layout">
        <section className="card">
          <div className="card-head">
            <h2>결과물 {items.length}개</h2>
            <input className="input input--sm" type="search" aria-label="결과물 찾기" placeholder="제목·대화로 찾기" value={q} onChange={(e) => setQ(e.target.value)} />
          </div>
          {items.length === 0 ? (
            <Empty icon="file" title={q ? '찾는 결과물이 없습니다' : '아직 결과물이 없습니다'}>
              에이전트가 "초안 저장" 도구로 남긴 보고서·답변·표가 여기 모입니다.
            </Empty>
          ) : (
            <ul className="rows">
              {items.map((x) => (
                <li key={x.id}>
                  <button type="button" className={`row row--button ${x.id === open ? 'is-current' : ''}`} aria-current={x.id === open ? 'true' : undefined} onClick={() => setParams({ open: x.id })}>
                    <span className="row__icon">
                      <Icon name={x.format === 'markdown' ? 'file' : 'columns'} size={16} />
                    </span>
                    <div className="row__main">
                      <span className="row__title">{x.title}</span>
                      <span className="row__meta">
                        <span>{FORMAT_LABEL[x.format]}</span>
                        {x.agent_name && <span>{x.agent_name}</span>}
                        <span>{x.trigger === 'schedule' ? '예약 실행' : '대화'}</span>
                        <span>{ago(x.created_at)}</span>
                      </span>
                    </div>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>
        {current ? <Preview ws={ws} space={space} a={current} /> : items.length > 0 && <div className="card card-pad art-hint">왼쪽에서 결과물을 고르면 여기서 미리 봅니다.</div>}
      </div>
    </div>
  );
}

function Preview({ ws, space, a }: { ws: string; space: string; a: Art }) {
  const [text, setText] = useState<string | null>(null);
  const [err, setErr] = useState('');
  const flash = useFlash();
  const url = `/api/w/${ws}/artifacts/${a.id}/content`;
  useEffect(() => {
    let live = true;
    setText(null);
    setErr('');
    fetch(`${url}?inline=1`, { credentials: 'same-origin' })
      .then(async (r) => {
        if (!r.ok) throw new Error(String(r.status));
        const t = await r.text();
        if (live) setText(t);
      })
      .catch(() => live && setErr('결과물을 읽지 못했습니다(삭제되었거나 볼 권한이 없습니다).'));
    return () => {
      live = false;
    };
  }, [url]);
  return (
    <section className="card art-preview" aria-label="결과물 미리보기">
      <div className="card-head">
        <h2>{a.title}</h2>
        <div className="btn-row">
          <button
            type="button"
            className="btn btn-ghost btn-sm"
            disabled={text === null}
            onClick={async () => {
              await navigator.clipboard?.writeText(text ?? '').catch(() => {});
              flash.show('결과물 내용을 복사했습니다.');
            }}
          >
            복사
          </button>
          <a className="btn btn-secondary btn-sm" href={url} download>
            내려받기
          </a>
        </div>
      </div>
      <div className="card-pad">
        <p className="small muted art-meta">
          {fmtDateTime(a.created_at)} · {fmtBytes(a.size)} · SHA-256 <span className="mono">{a.sha256.slice(0, 12)}</span>
          {a.conversation_id && (
            <>
              {' · '}
              <Link to={`/app/w/${ws}/spaces/${space}/chat/${a.conversation_id}`}>대화 보기</Link>
            </>
          )}
          {' · '}
          <Link to={`/app/w/${ws}/runs/${a.run_id}`}>실행 기록</Link>
        </p>
        {err ? <p className="danger-text small">{err}</p> : text === null ? <Loading /> : a.format === 'markdown' ? <Markdown text={text} /> : <pre className="code">{text}</pre>}
      </div>
    </section>
  );
}
/**
 * 실행 실시간 보기 — run_events 를 SSE 로 받는다. 끊기면 브라우저가 Last-Event-ID 로 이어 받고,
 * 새로 열면 지금까지 받은 마지막 seq 이후만 요청한다. seq 로 중복을 걸러 같은 사건을 두 번 보이지 않는다.
 * 창을 닫아도 실행은 서버에서 계속된다.
 */
import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router';
import { useQueryClient } from '@tanstack/react-query';
import { api, useAction, useApi } from '../../lib/api';
import type { RunEvent } from '../../lib/types';
import { ErrorNotice, Json, Money, RiskChip, RunPill } from '../../components/ui';
import { fmtTime, fmtMicros, until } from '../../lib/format';
import { RUN_ERROR, RUN_STATUS, TERMINAL_RUN, type RunErrorCode, type RunStatus } from '../../../shared/domain';

export function useRunEvents(ws: string, runId: string | null) {
  const [events, setEvents] = useState<RunEvent[]>([]);
  const [status, setStatus] = useState<string | null>(null);
  const seqRef = useRef(0);
  const qc = useQueryClient();
  useEffect(() => {
    setEvents([]);
    seqRef.current = 0;
    setStatus(null);
    if (!runId) return;
    let es: EventSource | null = null;
    let poll: ReturnType<typeof setInterval> | null = null;
    let closed = false;
    const add = (list: RunEvent[]) => {
      const fresh = list.filter((e) => e.seq > seqRef.current);
      if (!fresh.length) return;
      seqRef.current = fresh[fresh.length - 1]!.seq;
      setEvents((prev) => {
        const seen = new Set(prev.map((p) => p.seq));
        return [...prev, ...fresh.filter((e) => !seen.has(e.seq))];
      });
      const last = fresh[fresh.length - 1]!.type;
      if (['succeeded', 'failed', 'cancelled', 'expired', 'approval_required', 'input_required', 'connection_required', 'budget_paused', 'reconciliation_required', 'cancel_requested', 'resumed', 'approval_decided', 'input_received', 'reconciled'].includes(last)) {
        qc.invalidateQueries({ predicate: (q) => /\/(conversations|runs|approvals)\b|\/api\/w\/[^/]+$/.test(String(q.queryKey[0] ?? '')) });
      }
    };
    const startPoll = () => {
      if (poll) return;
      poll = setInterval(async () => {
        try {
          const r = await api<{ events: RunEvent[]; status: string }>(`/api/w/${ws}/runs/${runId}/events?after=${seqRef.current}`);
          add(r.events);
          setStatus(r.status);
          if (TERMINAL_RUN.includes(r.status as RunStatus) && poll) {
            clearInterval(poll);
            poll = null;
          }
        } catch {
          /* 다음 차례에 */
        }
      }, 2500);
    };
    if (typeof EventSource !== 'undefined') {
      es = new EventSource(`/api/w/${ws}/runs/${runId}/events?after=0`);
      es.addEventListener('run', (m) => {
        try {
          add([JSON.parse((m as MessageEvent).data)]);
        } catch {
          /* 무시 */
        }
      });
      es.addEventListener('end', (m) => {
        try {
          setStatus(JSON.parse((m as MessageEvent).data).status);
        } catch {
          /* 무시 */
        }
        es?.close();
        qc.invalidateQueries({ predicate: (q) => /\/(conversations|runs)\b/.test(String(q.queryKey[0] ?? '')) });
      });
      es.onerror = () => {
        // 서버가 25초마다 닫는다 — 브라우저가 Last-Event-ID 로 다시 붙는다. 영구 실패(4xx)면 폴링으로
        if (es && es.readyState === EventSource.CLOSED && !closed) startPoll();
      };
    } else startPoll();
    return () => {
      closed = true;
      es?.close();
      if (poll) clearInterval(poll);
    };
  }, [ws, runId, qc]);
  return { events, status };
}

