  approval_required: (d) => ({ text: `승인 대기${d.count ? ` ${d.count}건` : ''} — 승인하기 전에는 실행하지 않습니다.`, tone: 'warn' }),
  approval_decided: (d) => ({ text: `${d.tool} ${d.decision === 'approve' ? '승인' : '거절'}`, tone: d.decision === 'approve' ? 'ok' : 'warn' }),
  input_required: (d) => ({ text: `질문: ${d.question}`, tone: 'warn' }),
  input_received: () => ({ text: '답을 받아 이어 갑니다.' }),
  connection_required: (d) => ({ text: `연결 필요: ${d.connection} — ${d.message}`, tone: 'warn' }),
  budget_paused: (d) => ({ text: `멈춤: ${d.message}`, tone: 'warn' }),
  reconciliation_required: (d) => ({ text: `결과 확인 필요: ${d.tool} — ${d.message}`, tone: 'danger' }),
  reconciled: (d) => ({ text: `사람이 결과 확인: ${d.outcome === 'done' ? '실행됨' : '실행 안 됨'}` }),
  resumed: () => ({ text: '이어서 실행합니다.' }),
  cancel_requested: () => ({ text: '중지 요청 — 새 동작을 막습니다.', tone: 'warn' }),
  cancelled: (d) => ({ text: `중지됨${d.note ? ` — ${d.note}` : ''}`, tone: 'warn' }),
  succeeded: (d) => ({ text: `완료(${d.outcome === 'complete' ? '완료' : d.outcome === 'partial' ? '부분 완료' : '확인 필요'})`, tone: d.outcome === 'complete' ? 'ok' : 'warn' }),
  failed: (d) => ({ text: `실패: ${RUN_ERROR[d.code as RunErrorCode]?.label ?? d.code} — ${d.message}`, tone: 'danger' }),
  expired: (d) => ({ text: `기한 지남 — ${d.message}`, tone: 'warn' }),
  notice: (d) => ({ text: String(d.message ?? d.kind ?? '') }),
};

export function Timeline({ events }: { events: RunEvent[] }) {
  if (!events.length) return <p className="small muted">아직 기록이 없습니다.</p>;
  return (
    <ol className="timeline" aria-label="실행 기록">
      {events.map((e) => {
        const f = EV[e.type]?.(e.data) ?? { text: e.type };
        return (
          <li key={e.seq} className={f.tone ? `t-${f.tone}` : ''}>
            <div className="timeline__time">{fmtTime(e.at)}</div>
            <div className="timeline__body">{f.text}</div>
          </li>
        );
      })}
    </ol>
  );
}

