interface Mail {
  id: string;
  at: number;
  to: string[];
  subject: string;
  text: string;
  idempotencyKey: string | null;
}

export const mailsTo = async (to: string): Promise<Mail[]> => (await (await fetch(`${MAIL}/__mails?to=${encodeURIComponent(to)}`)).json()) as Mail[];

export async function waitNewMail(to: string, subject: RegExp, before: Set<string>, timeout = 15_000): Promise<Mail> {
  const end = performance.now() + timeout;
  while (performance.now() < end) {
    const m = (await mailsTo(to)).filter((x) => !before.has(x.id) && subject.test(x.subject)).at(-1);
    if (m) return m;
    await sleep(150);
  }
  throw new Error(`새 메일 없음: ${to} ${subject}`);
}

export class Api {
  constructor(
    public ctx: APIRequestContext,
    public email: string,
  ) {}
  async get(path: string, status = 200) {
    const r = await this.ctx.get(path);
    await expectStatus(r, status, `GET ${path}`);
    return r.status() < 300 ? r.json() : r.json().catch(() => null);
  }
  async post(path: string, data: unknown = {}, status = 200, headers: Record<string, string> = {}) {
    const r = await this.ctx.post(path, { data, headers: { 'Content-Type': 'application/json', ...headers } });
    await expectStatus(r, status, `POST ${path}`);
    return r.json().catch(() => null);
  }
  async put(path: string, data: unknown, status = 200) {
    const r = await this.ctx.put(path, { data, headers: { 'Content-Type': 'application/json' } });
    await expectStatus(r, status, `PUT ${path}`);
    return r.json().catch(() => null);
  }
  async del(path: string, status = 200) {
    const r = await this.ctx.delete(path);
    await expectStatus(r, status, `DELETE ${path}`);
    return r.json().catch(() => null);
  }
  async raw(method: 'GET' | 'POST' | 'PUT' | 'DELETE', path: string, data?: unknown, headers: Record<string, string> = {}) {
    return this.ctx.fetch(path, { method, data, headers: { ...(data !== undefined && typeof data !== 'string' && !Buffer.isBuffer(data) ? { 'Content-Type': 'application/json' } : {}), ...headers } });
  }
}

export async function expectStatus(r: APIResponse, status: number, label: string) {
  if (r.status() !== status) throw new Error(`${label} → ${r.status()} (기대 ${status}): ${(await r.text()).slice(0, 500)}`);
}

export async function login(addr: string): Promise<Api> {
  const ctx = await request.newContext({ baseURL: BASE, extraHTTPHeaders: { Origin: BASE, 'CF-Connecting-IP': fakeIp() } });
  const before = new Set((await mailsTo(addr)).map((m) => m.id));
  const s = await ctx.post('/api/auth/email-otp/send-verification-otp', { data: { email: addr, type: 'sign-in' } });
  expect(s.status(), await s.text()).toBe(200);
  const code = (await waitNewMail(addr, /로그인 코드/, before)).subject.match(/\d{6}/)![0];
  const v = await ctx.post('/api/auth/sign-in/email-otp', { data: { email: addr, otp: code } });
  expect(v.status(), await v.text()).toBe(200);
  return new Api(ctx, addr);
}

